
/* ——— SONVS · 界面音效 ———
   九条 CC0 成品（Freesound，逐条公共领域），按 MPEG 帧边界截到够用的长度，
   播放时用增益斜坡收尾，所以听不见硬切。一次动作只出一声，规矩是这样定的：

     · 按下时就能从目标判出来该响哪一声的（进入、三个小窗、装备动作、上下翻页），
       在 pointerdown 上当场响 —— 等 click 再响，手感上会慢半拍。
     · 要等结果才知道响哪一声的（地图点没点着地名、商店买不买得起、
       图谱那一下是拖还是点），把它划进静音区，由那几处代码自己喊。
   两边不重叠，所以不会一次动作出两声。

   音频不走 fetch：制品页那种收紧的 CSP 会把 fetch('data:…') 拦下来，
   atob 直接转字节谁也拦不住。解码要等第一次手势——浏览器不许没手势就出声。 */
(function(){
  var SND={"click":{"g":1.25,"f":60,"b":""},"slide":{"g":0.88,"f":50,"b":""},"pick":{"g":1.03,"f":110,"b":""},"intro":{"g":0.87,"f":150,"b":""},"send":{"g":2.12,"f":80,"b":""},"gear":{"g":1.86,"f":70,"b":""},"site":{"g":5.24,"f":30,"b":""},"node":{"g":0.9,"f":80,"b":""},"deny":{"g":0.68,"f":90,"b":""}};
  var AC=null,MAS=null,BUF={},PEND={},VOL=null,LAST={},booted=0;

  function vol(){
    if(VOL==null){
      var v=parseFloat(localStorage.getItem('rome_sfxvol'));
      VOL=(isFinite(v)&&v>=0&&v<=100)?v/100:0.7;
    }
    return VOL;
  }
  function bytes(s){var n=s.length,u=new Uint8Array(n);
    for(var i=0;i<n;i++)u[i]=s.charCodeAt(i);return u.buffer;}
  function load(){
    var ks=Object.keys(SND),i=0;
    (function nx(){
      if(i>=ks.length)return;
      var k=ks[i++],raw;
      try{raw=bytes(atob(SND[k].b));}catch(e){return nx();}
      var once=0;
      var ok=function(b){if(once++)return;BUF[k]=b;
        var q=PEND[k];PEND[k]=0;
        if(q){var nn=(window.performance&&performance.now)?performance.now():+new Date();
              if(nn-q<500)setTimeout(function(){play(k);},0);}
        nx();};
      var no=function(){if(once++)return;nx();};
      try{var p=AC.decodeAudioData(raw,ok,no);if(p&&p.then)p.then(ok,no);}catch(e){no();}
    })();
  }
  function ctx(){
    if(!AC){
      try{
        AC=new (window.AudioContext||window.webkitAudioContext)();
        MAS=AC.createGain();MAS.gain.value=1;MAS.connect(AC.destination);
      }catch(e){AC=null;return null;}
      if(!booted){booted=1;load();}
    }
    if(AC.state==='suspended'){try{AC.resume();}catch(e){}}
    return AC;
  }
  function play(k){
    var s=SND[k];if(!s)return;
    var v=vol();if(!(v>0))return;
    var c=ctx();if(!c)return;
    /* 不拿 state==='running' 当门槛。resume() 是异步的，而第一声偏偏就出在
       触发 resume 的那一下手势里——按这个门槛拦，开场那一记 INTRARE 永远是哑的。
       挂起状态下 currentTime 是冻住的，此刻排进去的 start(t) 会在恢复的那一刻从头响。 */
    var b=BUF[k];
    if(!b){                     /* 还没解出来：记一笔，解完了补响（只补 500 毫秒内的） */
      PEND[k]=(window.performance&&performance.now)?performance.now():+new Date();
      return;
    }
    /* 同一条 55 毫秒内只响一次：滑动切换那几处一秒能来十几下，
       叠在一起就是一片糊音，还会把增益堆上去。 */
    var now=(window.performance&&performance.now)?performance.now():+new Date();
    if(now-(LAST[k]||0)<55)return;
    LAST[k]=now;
    try{
      var t=c.currentTime,d=b.duration,f=Math.min(s.f/1000,d*0.6);
      var g=c.createGain(),src=c.createBufferSource();
      src.buffer=b;
      g.gain.setValueAtTime(s.g*v,t);
      g.gain.setValueAtTime(s.g*v,t+Math.max(0,d-f));
      g.gain.linearRampToValueAtTime(0.0001,t+d);
      src.connect(g);g.connect(MAS);
      src.start(t);src.stop(t+d+0.02);
    }catch(e){}
  }
  window.SX=function(k){try{play(k);}catch(e){}};
  window.SX.vol=function(p){
    VOL=Math.max(0,Math.min(1,(+p||0)/100));
    try{localStorage.setItem('rome_sfxvol',''+Math.round(VOL*100));}catch(e){}
  };
  window.SX.get=function(){return Math.round(vol()*100);};

  /* 按下的目标 → 该响哪一声。表里没有、又不在静音区的，一律走兜底点击音。 */
  var MAP=[['#iBtn,#intro','intro'],
           ['#arrMap,#arrArm,#arrShop','pick'],
           ['#armWrap [data-act]','gear'],
           ['[data-mv]','slide']];
  /* 静音区：这几处该响哪一声要看结果，交给各自的代码喊 */
  var MUTE='#gmapCv,#menuCv,#zjGraphSvg,#stage,#rail,#lsTrack,#gSend,#shopWrap [data-buy]'
    /* 铸局拣人那几处：立绘转没转要看点的是不是同一位，交给 fePortTurn／fePerPick 自己喊。
       立绘上那几枚钮（✕、确认、左右箭头）也一并划进来——它们各自引出的是一次
       立绘滑动，那一记 slide 已经够了，再叠一记兜底点击音就成了两声。 */
    +',#fePreList .fePre,#feSocList .feCard,#feArtX,#feArtOk,#feArtP,#feArtN';
  function clickable(t){
    for(var i=0;i<6&&t&&t.nodeType===1;i++,t=t.parentNode){
      if(t.getAttribute&&t.getAttribute('data-nosfx')!=null)return false;
      var cs=null;try{cs=getComputedStyle(t);}catch(e){}
      if(cs&&cs.cursor==='pointer')return true;
    }
    return false;
  }
  addEventListener('pointerdown',function(e){
    ctx();                                   /* 借这一下手势解锁音频，顺带开始解码 */
    if(e.isPrimary===false)return;
    var t=e.target;if(!t||!t.closest)return;
    /* 一律经 window.SX 出声：外面那些「结果决定音效」的地方喊的也是它，
       两条路合到一处，测起来只要盯这一个口子。 */
    for(var i=0;i<MAP.length;i++){if(t.closest(MAP[i][0])){window.SX(MAP[i][1]);return;}}
    if(t.closest(MUTE))return;
    if(clickable(t))window.SX('click');
  },true);
  addEventListener('keydown',function(){ctx();},true);

  /* 设置里那根「SONVS · 音效」拉杆原来接的是 AU（一套从未接线的程序化音源，
     AU.on 恒 false），拖了等于拖空气。现在把它接到这里来。 */
  function bindSlider(){
    var el=document.getElementById('cfgVol');if(!el)return;
    el.value=window.SX.get();
    try{el.style.setProperty('--rv',window.SX.get()+'%');}catch(e){}
    el.addEventListener('input',function(){
      window.SX.vol(this.value);
      if(!bindSlider._p){bindSlider._p=1;setTimeout(function(){bindSlider._p=0;},220);window.SX('click');}
    });
  }
  if(document.readyState==='loading')addEventListener('DOMContentLoaded',bindSlider);
  else bindSlider();
  /* 建上下文与解码都不需要手势（建出来是 suspended，解码照样跑）。
     等第一次点下去才开始解，那一声必然赶不上——开场那一记正好就是第一声。 */
  try{ctx();}catch(e){}
})();
